func unsafeServer3() {
	http.HandleFunc("/payment", paymentHandler)
	
	// 极度危险：明文 HTTP + 公网地址
	// 任何人都可以拦截支付信息
	log.Fatal(http.ListenAndServe("0.0.0.0:8080", nil))
