	'safefile://safe_https_server.go': <<<SAFE
package main

import (
	"crypto/tls"
	"log"
	"net/http"
	"time"
)

// 方案 1: 使用 ListenAndServeTLS（最简单）
func safeServer1() {
	http.HandleFunc("/", homeHandler)
	http.HandleFunc("/login", loginHandler)
	
	// 安全：使用 HTTPS
	log.Println("Starting HTTPS server on :8443")
	log.Fatal(http.ListenAndServeTLS(
		":8443",
		"cert.pem",  // SSL 证书
		"key.pem",   // 私钥
		nil,
	))
}

// 方案 2: 配置安全的 http.Server（推荐）
func safeServer2() {
	mux := http.NewServeMux()
	mux.HandleFunc("/", homeHandler)
	mux.HandleFunc("/api/data", apiHandler)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
		
		// TLS 安全配置
		TLSConfig: &tls.Config{
			MinVersion:               tls.VersionTLS12, // 最低 TLS 1.2
			CurvePreferences:         []tls.CurveID{tls.CurveP521, tls.CurveP384, tls.CurveP256},
			PreferServerCipherSuites: true,
			CipherSuites: []uint16{
				tls.TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,
				tls.TLS_ECDHE_RSA_WITH_AES_256_CBC_SHA,
				tls.TLS_RSA_WITH_AES_256_GCM_SHA384,
				tls.TLS_RSA_WITH_AES_256_CBC_SHA,
			},
		},
	}

	log.Println("Starting secure HTTPS server on :8443")
	log.Fatal(server.ListenAndServeTLS("cert.pem", "key.pem"))
}

func homeHandler(w http.ResponseWriter, r *http.Request) {
	// 添加安全响应头
	w.Header().Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	
	w.Write([]byte("Welcome to secure site!"))
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	// 密码通过 HTTPS 加密传输，安全
	password := r.FormValue("password")
	
	if authenticate(password) {
		http.SetCookie(w, &http.Cookie{
			Name:     "session",
			Value:    generateSessionToken(),
			HttpOnly: true,
			Secure:   true, // 只通过 HTTPS 传输
			SameSite: http.SameSiteStrictMode,
		})
	}
}

func apiHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"status": "secure"}`))
}

func authenticate(password string) bool {
	return true // 示例
}

func generateSessionToken() string {
	return "secure_token"
}

func main() {
	safeServer2()
}
